from api_common import *
import urllib.request
def helper(p): return urllib.request.urlopen(f'http://localhost:{PORT_A}{p}').read().decode()
def ck(name, cond, extra=''): print(('✅ ' if cond else '🔴 ') + name + (('  -> ' + str(extra)) if extra != '' else ''), flush=True)
def login_ui(page, user, pw):
    page.wait_for_selector('#bsdemo-login'); page.fill('#bsl-user', user); page.fill('#bsl-pass', pw); page.click('#bsl-go')
def phase(page):
    ctx = page.context
    step('A. first load without any credentials shows the login screen')
    page.goto(BASE + 'crm.html'); page.wait_for_selector('#bsdemo-login')
    ck('login modal appears, bar says not connected', 'לא מחובר' in page.inner_text('#bsdemo-bar'), page.inner_text('#bsdemo-bar')[:60])
    step('B. wrong password')
    login_ui(page, 'ora', 'wrong-password-123'); page.wait_for_function("document.getElementById('bsl-msg').textContent.length > 3 && !document.getElementById('bsl-msg').textContent.includes('בודק')")
    ck('wrong password shows the generic message and keeps the screen', page.inner_text('#bsl-msg') == 'שם משתמש או סיסמה שגויים' and page.locator('#bsdemo-login').count() == 1, page.inner_text('#bsl-msg'))
    step('C. correct login (editor)')
    page.fill('#bsl-user', 'ora'); page.fill('#bsl-pass', 'Long-Passw0rd-123'); page.click('#bsl-go')
    page.wait_for_function("typeof globalCustomers !== 'undefined' && globalCustomers.length >= 2")
    ck('CRM loads customers after login', page.evaluate('globalCustomers.length') == 2)
    cfgj = page.evaluate('bsDemo.config()'); ck('config shows user, role and method', cfgj['user'] == 'ora' and cfgj['role'] == 'editor' and cfgj['method'] == 'password', cfgj)
    ck('token is in sessionStorage only (not in localStorage)', page.evaluate("!!sessionStorage.getItem('bs:token') && !localStorage.getItem('bs:token')"))
    ck('bar shows user and role, with a logout link', 'ora' in page.inner_text('#bsdemo-bar') and 'עריכה' in page.inner_text('#bsdemo-bar') and page.locator('#bsdemo-logout').count() == 1)
    step('D. editor can write')
    r = page.evaluate("new Promise(res => google.script.run.withSuccessHandler(x => res(x)).withFailureHandler(e => res({err: e.message})).saveConsumptionAnalysis(JSON.stringify({clientId: 'BS-1001', consumptionAnalysis: {t: 1}})))")
    ck('write succeeds', r.get('ok') is True, r)
    step('E. a second tab gets the session without a login screen (BroadcastChannel)')
    p2 = ctx.new_page(); p2.set_default_timeout(60000); p2.goto(BASE + 'crm.html')
    p2.wait_for_function("typeof globalCustomers !== 'undefined' && globalCustomers.length >= 2")
    ck('second tab loaded customers without a login modal', p2.locator('#bsdemo-login').count() == 0 and p2.evaluate('bsDemo.config().user') == 'ora')
    step('F. logout in one tab logs out the other')
    page.click('#bsdemo-logout'); page.wait_for_timeout(1800)
    ck('first tab token cleared', page.evaluate("!sessionStorage.getItem('bs:token')"))
    ck('second tab received the logout', p2.evaluate("!sessionStorage.getItem('bs:token')"))
    p2.evaluate("window.__r = null; google.script.run.withSuccessHandler(x => window.__r = 'ok').withFailureHandler(e => window.__r = e.message).getInitialData()")
    p2.wait_for_selector('#bsdemo-login'); ck('after logout the next call asks to log in again', True); p2.click('#bsl-cancel'); p2.wait_for_function("window.__r !== null")
    ck('cancel makes the call fail cleanly', 'לא בוצעה התחברות' in p2.evaluate('window.__r'), p2.evaluate('window.__r')); p2.close()
    step('G. view-only user')
    page.goto(BASE + 'crm.html'); login_ui(page, 'viewer1', 'Another-Passw0rd-1')
    page.wait_for_function("typeof globalCustomers !== 'undefined' && globalCustomers.length >= 2")
    ck('viewer sees the role in the bar', 'צפייה בלבד' in page.inner_text('#bsdemo-bar'))
    n_before = sum(1 for e in json.load(urllib.request.urlopen(f'http://localhost:{PORT_A}/__log'))['log'] if e.get('action') == 'saveConsumptionAnalysis')
    r = page.evaluate("new Promise(res => google.script.run.withSuccessHandler(x => res({ok: true})).withFailureHandler(e => res({code: e.code, msg: e.message})).saveConsumptionAnalysis(JSON.stringify({clientId: 'BS-1001', consumptionAnalysis: {t: 2}})))")
    n_after = sum(1 for e in json.load(urllib.request.urlopen(f'http://localhost:{PORT_A}/__log'))['log'] if e.get('action') == 'saveConsumptionAnalysis')
    ck('write is blocked in the browser (code forbidden) without calling the server', r.get('code') == 'forbidden' and n_after == n_before, r)
    tok = page.evaluate("JSON.parse(sessionStorage.getItem('bs:token')).token")
    r2 = page.evaluate("(t) => fetch(bsDemo.config().url, {method: 'POST', headers: {'Content-Type': 'text/plain;charset=utf-8'}, body: JSON.stringify({action: 'saveCustomerData', token: t, args: ['{}']})}).then(r => r.json())", tok)
    ck('server also refuses the viewer token (forbidden)', r2.get('code') == 'forbidden', r2)
    ck('viewer can still read', page.evaluate("new Promise(res => google.script.run.withSuccessHandler(x => res(x.customers.length)).getInitialData())") == 2)
    page.click('#bsdemo-logout'); page.wait_for_timeout(1500)
    step('H. session expires on the server mid-use: the call waits, asks to log in again, then completes')
    page.goto(BASE + 'crm.html'); login_ui(page, 'ora', 'Long-Passw0rd-123'); page.wait_for_function("typeof globalCustomers !== 'undefined' && globalCustomers.length >= 2")
    helper('/__expire')
    page.evaluate("window.__res = null; google.script.run.withSuccessHandler(x => window.__res = {n: x.customers.length}).withFailureHandler(e => window.__res = {err: e.message}).getInitialData()")
    page.wait_for_selector('#bsdemo-login'); ck('login screen shows the expiry reason', 'פגה' in page.inner_text('#bsl-reason'), page.inner_text('#bsl-reason'))
    page.fill('#bsl-user', 'ora'); page.fill('#bsl-pass', 'Long-Passw0rd-123'); page.click('#bsl-go'); page.wait_for_function("window.__res !== null")
    ck('the original call completed after re-login', page.evaluate('window.__res').get('n') == 2, page.evaluate('window.__res'))
    step('J. lockout after 5 wrong attempts in the UI')
    page.click('#bsdemo-logout'); page.wait_for_timeout(1500); page.goto(BASE + 'crm.html'); page.wait_for_selector('#bsdemo-login')
    for i in range(5):
        page.fill('#bsl-user', 'ora'); page.fill('#bsl-pass', 'bad-password-%d' % i); page.click('#bsl-go'); page.wait_for_function("document.getElementById('bsl-go').disabled === false")
    page.fill('#bsl-user', 'ora'); page.fill('#bsl-pass', 'Long-Passw0rd-123'); page.click('#bsl-go'); page.wait_for_function("document.getElementById('bsl-msg').textContent.includes('ניסיונות')")
    ck('right password is refused while locked', 'יותר מדי ניסיונות' in page.inner_text('#bsl-msg'), page.inner_text('#bsl-msg')); helper('/__unlock')
    page.click('#bsl-cancel')
    step('K. legacy service key still works (no login screen)')
    page.evaluate("sessionStorage.clear(); localStorage.setItem('bs:api', JSON.stringify({url: '%s', key: 'TESTKEY', exportMode: 'server'}))" % API_URL)
    page.goto(BASE + 'crm.html'); page.wait_for_function("typeof globalCustomers !== 'undefined' && globalCustomers.length >= 2")
    ck('service key mode: customers load, bar shows the key mode', page.locator('#bsdemo-login').count() == 0 and 'מפתח שירות' in page.inner_text('#bsdemo-bar'))
    page.evaluate("localStorage.setItem('bs:api', JSON.stringify({url: '%s', exportMode: 'server'}))" % API_URL)
    lg = json.load(urllib.request.urlopen(f'http://localhost:{PORT_A}/__log'))
    ck('no CORS preflight (OPTIONS) was ever sent; all POSTs are text/plain', not any(e['m'] == 'OPTIONS' for e in lg['log']) and all(e['ct'].startswith('text/plain') for e in lg['log'] if e['m'] == 'POST'))
run(phase, reset=True, preset_cfg=True, with_key=False)
